syntax = "proto3";

package sandbox.v0;

// FilesystemService manages small files rooted at /home/user.
service FilesystemService {
  rpc WriteFile(WriteFileRequest) returns (WriteFileResponse);
  rpc ReadFile(ReadFileRequest) returns (ReadFileResponse);
}

message WriteFileRequest {
  // Path is relative to /home/user. Implementations may also accept an
  // absolute path under /home/user, but must reject every escaping path.
  string path = 1;
  bytes content = 2;
  // Create missing parent directories when true.
  bool create_parents = 3;
}

message WriteFileResponse {
  uint64 bytes_written = 1;
}

message ReadFileRequest {
  // Path follows the same scoping rules as WriteFileRequest.path.
  string path = 1;
}

message ReadFileResponse {
  bytes content = 1;
}

syntax = "proto3";

package sandbox.v0;

// CommandService starts one fresh process per request.
service CommandService {
  rpc ExecuteCommand(ExecuteCommandRequest) returns (ExecuteCommandResponse);
}

message ExecuteCommandRequest {
  // Argv contains the executable followed by its arguments. The service does
  // not invoke a shell unless the caller explicitly requests one in argv.
  repeated string argv = 1;
  // Working directory relative to /home/user. Empty means /home/user.
  string working_directory = 2;
  // Extra environment variables for the process.
  map<string, string> environment = 3;
  // Zero selects the service default. A timed-out process returns DEADLINE_EXCEEDED.
  uint64 timeout_ms = 4;
}

message ExecuteCommandResponse {
  bytes stdout = 1;
  bytes stderr = 2;
  int32 exit_code = 3;
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let protos = ["proto/v0/command.proto", "proto/v0/filesystem.proto"];

    tonic_build::configure()
        .file_descriptor_set_path("sandbox_descriptor.bin")
        .compile_protos(&protos, &["proto"])?;

    for proto in protos {
        println!("cargo:rerun-if-changed={proto}");
    }

    Ok(())
}

use std::env;

use sandbox::v0::{
    ExecuteCommandRequest, ExecuteCommandResponse, ReadFileRequest, ReadFileResponse,
    WriteFileRequest, WriteFileResponse,
    command_service_server::{CommandService, CommandServiceServer},
    filesystem_service_server::{FilesystemService, FilesystemServiceServer},
};
use tonic::{Request, Response, Status, transport::Server};

mod sandbox {
    pub mod v0 {
        tonic::include_proto!("sandbox.v0");
    }
}

const FILE_DESCRIPTOR_SET: &[u8] = tonic::include_file_descriptor_set!("sandbox_descriptor");

#[derive(Default)]
struct SandboxService;

#[tonic::async_trait]
impl FilesystemService for SandboxService {
    async fn write_file(
        &self,
        _request: Request<WriteFileRequest>,
    ) -> Result<Response<WriteFileResponse>, Status> {
        Err(Status::unimplemented("WriteFile is not implemented yet"))
    }

    async fn read_file(
        &self,
        _request: Request<ReadFileRequest>,
    ) -> Result<Response<ReadFileResponse>, Status> {
        Err(Status::unimplemented("ReadFile is not implemented yet"))
    }
}

#[tonic::async_trait]
impl CommandService for SandboxService {
    async fn execute_command(
        &self,
        _request: Request<ExecuteCommandRequest>,
    ) -> Result<Response<ExecuteCommandResponse>, Status> {
        Err(Status::unimplemented(
            "ExecuteCommand is not implemented yet",
        ))
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let address = env::var("AGENT_SANDBOX_LISTEN")
        .unwrap_or_else(|_| "0.0.0.0:8080".into())
        .parse()?;

    let filesystem = FilesystemServiceServer::new(SandboxService);
    let command = CommandServiceServer::new(SandboxService);
    let (mut health_reporter, health) = tonic_health::server::health_reporter();
    health_reporter
        .set_serving::<FilesystemServiceServer<SandboxService>>()
        .await;
    health_reporter
        .set_serving::<CommandServiceServer<SandboxService>>()
        .await;

    let reflection = tonic_reflection::server::Builder::configure()
        .register_encoded_file_descriptor_set(FILE_DESCRIPTOR_SET)
        .register_encoded_file_descriptor_set(tonic_health::pb::FILE_DESCRIPTOR_SET)
        .build_v1()?;

    eprintln!("agent-sandbox gRPC service listening on {address}");
    Server::builder()
        .add_service(health)
        .add_service(reflection)
        .add_service(filesystem)
        .add_service(command)
        .serve(address)
        .await?;

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use tonic::Code;

    #[tokio::test]
    async fn filesystem_handlers_are_explicit_stubs() {
        let service = SandboxService;
        let error = service
            .read_file(Request::new(ReadFileRequest {
                path: "fixture.txt".into(),
            }))
            .await
            .expect_err("stub must reject calls");

        assert_eq!(error.code(), Code::Unimplemented);
    }

    #[tokio::test]
    async fn command_handler_is_an_explicit_stub() {
        let service = SandboxService;
        let error = service
            .execute_command(Request::new(ExecuteCommandRequest {
                argv: vec!["true".into()],
                ..Default::default()
            }))
            .await
            .expect_err("stub must reject calls");

        assert_eq!(error.code(), Code::Unimplemented);
    }
}

