use std::path::{Component, Path, PathBuf};
use std::{fs, io};

use tokio::process::Command;
use tokio::time::{Duration, timeout};
use tonic::{Request, Response, Status};
use tracing::info;

use crate::sandbox::v0::{
    ExecuteCommandRequest, ExecuteCommandResponse, HealthCheckRequest, HealthCheckResponse,
    ReadFileRequest, ReadFileResponse, ServingStatus, WriteFileRequest, WriteFileResponse,
    command_service_server::CommandService, filesystem_service_server::FilesystemService,
    health_service_server::HealthService,
};

const DEFAULT_COMMAND_TIMEOUT_MS: u64 = 30_000;
const MAX_COMMAND_TIMEOUT_MS: u64 = 300_000;

#[derive(Clone)]
pub(crate) struct SandboxService {
    root: PathBuf,
}

impl SandboxService {
    pub(crate) fn new(root: impl AsRef<Path>) -> io::Result<Self> {
        fs::create_dir_all(root.as_ref())?;
        Ok(Self {
            root: fs::canonicalize(root)?,
        })
    }

    fn relative_path(&self, requested: &str) -> Result<PathBuf, Status> {
        if requested.is_empty() {
            return Err(Status::invalid_argument("path must not be empty"));
        }

        let requested = Path::new(requested);
        let relative = if requested.is_absolute() {
            requested.strip_prefix(&self.root).map_err(|_| {
                Status::permission_denied("absolute path must be under the sandbox root")
            })?
        } else {
            requested
        };

        let mut clean = PathBuf::new();
        for component in relative.components() {
            match component {
                Component::Normal(part) => clean.push(part),
                Component::CurDir => {}
                Component::ParentDir | Component::RootDir | Component::Prefix(_) => {
                    return Err(Status::permission_denied("path escapes the sandbox root"));
                }
            }
        }

        if clean.as_os_str().is_empty() {
            return Err(Status::invalid_argument("path must name an entry"));
        }
        Ok(clean)
    }

    fn existing_path(&self, requested: &str) -> Result<PathBuf, Status> {
        let relative = self.relative_path(requested)?;
        let canonical = fs::canonicalize(self.root.join(relative)).map_err(io_status)?;
        self.ensure_scoped(canonical)
    }

    fn writable_path(&self, requested: &str, create_parents: bool) -> Result<PathBuf, Status> {
        let relative = self.relative_path(requested)?;
        let candidate = self.root.join(relative);

        if candidate.exists() {
            return self.ensure_scoped(fs::canonicalize(candidate).map_err(io_status)?);
        }

        let parent = candidate
            .parent()
            .ok_or_else(|| Status::invalid_argument("path has no parent"))?;
        if create_parents {
            fs::create_dir_all(parent).map_err(io_status)?;
        }
        let canonical_parent = fs::canonicalize(parent).map_err(io_status)?;
        let canonical_parent = self.ensure_scoped(canonical_parent)?;
        let filename = candidate
            .file_name()
            .ok_or_else(|| Status::invalid_argument("path must name a file"))?;
        Ok(canonical_parent.join(filename))
    }

    fn ensure_scoped(&self, path: PathBuf) -> Result<PathBuf, Status> {
        if path.starts_with(&self.root) {
            Ok(path)
        } else {
            Err(Status::permission_denied("path escapes the sandbox root"))
        }
    }

    fn working_directory(&self, requested: &str) -> Result<PathBuf, Status> {
        let directory = if requested.is_empty() {
            self.root.clone()
        } else {
            self.existing_path(requested)?
        };
        if directory.is_dir() {
            Ok(directory)
        } else {
            Err(Status::invalid_argument("working directory is not a directory"))
        }
    }
}

#[tonic::async_trait]
impl FilesystemService for SandboxService {
    async fn write_file(
        &self,
        request: Request<WriteFileRequest>,
    ) -> Result<Response<WriteFileResponse>, Status> {
        let request = request.into_inner();
        let path = self.writable_path(&request.path, request.create_parents)?;
        fs::write(&path, &request.content).map_err(io_status)?;
        info!(path = %path.display(), bytes = request.content.len(), "wrote file");
        Ok(Response::new(WriteFileResponse {
            bytes_written: request.content.len() as u64,
        }))
    }

    async fn read_file(
        &self,
        request: Request<ReadFileRequest>,
    ) -> Result<Response<ReadFileResponse>, Status> {
        let path = self.existing_path(&request.into_inner().path)?;
        if !path.is_file() {
            return Err(Status::invalid_argument("path is not a file"));
        }
        let content = fs::read(&path).map_err(io_status)?;
        info!(path = %path.display(), bytes = content.len(), "read file");
        Ok(Response::new(ReadFileResponse { content }))
    }
}

#[tonic::async_trait]
impl HealthService for SandboxService {
    async fn check(
        &self,
        _request: Request<HealthCheckRequest>,
    ) -> Result<Response<HealthCheckResponse>, Status> {
        Ok(Response::new(HealthCheckResponse {
            status: ServingStatus::Serving.into(),
        }))
    }
}

#[tonic::async_trait]
impl CommandService for SandboxService {
    async fn execute_command(
        &self,
        request: Request<ExecuteCommandRequest>,
    ) -> Result<Response<ExecuteCommandResponse>, Status> {
        let request = request.into_inner();
        let (program, arguments) = request
            .argv
            .split_first()
            .ok_or_else(|| Status::invalid_argument("argv must contain an executable"))?;
        let working_directory = self.working_directory(&request.working_directory)?;
        let timeout_ms = match request.timeout_ms {
            0 => DEFAULT_COMMAND_TIMEOUT_MS,
            value if value <= MAX_COMMAND_TIMEOUT_MS => value,
            _ => {
                return Err(Status::invalid_argument(format!(
                    "timeout_ms must not exceed {MAX_COMMAND_TIMEOUT_MS}"
                )));
            }
        };

        info!(program, cwd = %working_directory.display(), timeout_ms, "executing command");
        let mut command = Command::new(program);
        command
            .args(arguments)
            .current_dir(working_directory)
            .envs(request.environment)
            .kill_on_drop(true);

        let output = timeout(Duration::from_millis(timeout_ms), command.output())
            .await
            .map_err(|_| Status::deadline_exceeded("command timed out"))?
            .map_err(|error| Status::internal(format!("failed to execute command: {error}")))?;

        let exit_code = output.status.code().unwrap_or(-1);
        info!(program, exit_code, "command completed");
        Ok(Response::new(ExecuteCommandResponse {
            stdout: output.stdout,
            stderr: output.stderr,
            exit_code,
        }))
    }
}

fn io_status(error: io::Error) -> Status {
    match error.kind() {
        io::ErrorKind::NotFound => Status::not_found(error.to_string()),
        io::ErrorKind::PermissionDenied => Status::permission_denied(error.to_string()),
        io::ErrorKind::AlreadyExists | io::ErrorKind::InvalidInput => {
            Status::invalid_argument(error.to_string())
        }
        _ => Status::internal(error.to_string()),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;
    use tonic::Code;

    fn service() -> (TempDir, SandboxService) {
        let root = TempDir::new().expect("create temporary root");
        let service = SandboxService::new(root.path()).expect("create service");
        (root, service)
    }

    #[tokio::test]
    async fn writes_and_reads_nested_files() {
        let (_root, service) = service();
        service
            .write_file(Request::new(WriteFileRequest {
                path: "fixtures/example.txt".into(),
                content: b"hello".to_vec(),
                create_parents: true,
            }))
            .await
            .expect("write file");

        let response = service
            .read_file(Request::new(ReadFileRequest {
                path: "fixtures/example.txt".into(),
            }))
            .await
            .expect("read file")
            .into_inner();
        assert_eq!(response.content, b"hello");
    }

    #[tokio::test]
    async fn rejects_parent_path_escape() {
        let (_root, service) = service();
        let error = service
            .write_file(Request::new(WriteFileRequest {
                path: "../escape.txt".into(),
                content: Vec::new(),
                create_parents: true,
            }))
            .await
            .expect_err("escape must fail");
        assert_eq!(error.code(), Code::PermissionDenied);
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn rejects_symlink_path_escape() {
        use std::os::unix::fs::symlink;

        let (root, service) = service();
        let outside = TempDir::new().expect("create outside directory");
        symlink(outside.path(), root.path().join("outside")).expect("create symlink");
        let error = service
            .write_file(Request::new(WriteFileRequest {
                path: "outside/escape.txt".into(),
                content: Vec::new(),
                create_parents: false,
            }))
            .await
            .expect_err("symlink escape must fail");
        assert_eq!(error.code(), Code::PermissionDenied);
    }

    #[tokio::test]
    async fn executes_each_command_in_a_fresh_process() {
        let (_root, service) = service();
        let response = service
            .execute_command(Request::new(ExecuteCommandRequest {
                argv: vec!["sh".into(), "-c".into(), "printf '%s' \"$VALUE\"".into()],
                environment: [("VALUE".into(), "available".into())].into(),
                ..Default::default()
            }))
            .await
            .expect("execute command")
            .into_inner();
        assert_eq!(response.stdout, b"available");
        assert!(response.stderr.is_empty());
        assert_eq!(response.exit_code, 0);
    }
}

use std::collections::HashSet;
use std::env;
use std::error::Error;
use std::path::{Path as FsPath, PathBuf};
use std::sync::Arc;

use futures_util::TryStreamExt;
use object_store::aws::AmazonS3Builder;
use object_store::path::Path;
use object_store::{ObjectMeta, ObjectStore};
use tracing::{info, warn};
use walkdir::WalkDir;

pub(crate) type StorageResult<T> = Result<T, Box<dyn Error + Send + Sync>>;

#[derive(Clone)]
pub(crate) struct S3Sync {
    store: Arc<dyn ObjectStore>,
    prefix: Path,
}

impl S3Sync {
    pub(crate) fn from_env() -> StorageResult<Option<Self>> {
        let Some(bucket) = env::var("AGENT_SANDBOX_S3_BUCKET")
            .ok()
            .filter(|value| !value.is_empty())
        else {
            warn!("AGENT_SANDBOX_S3_BUCKET is unset; S3 synchronization is disabled");
            return Ok(None);
        };

        let mut builder = AmazonS3Builder::from_env()
            .with_bucket_name(bucket)
            .with_virtual_hosted_style_request(false);
        if let Ok(endpoint) = env::var("AGENT_SANDBOX_S3_ENDPOINT") {
            builder = builder
                .with_allow_http(endpoint.starts_with("http://"))
                .with_endpoint(endpoint);
        }

        let prefix = env::var("AGENT_SANDBOX_S3_PREFIX").unwrap_or_else(|_| "home".into());
        Ok(Some(Self {
            store: Arc::new(builder.build()?),
            prefix: Path::parse(prefix)?,
        }))
    }

    pub(crate) async fn sync_down(&self, root: &FsPath) -> StorageResult<()> {
        tokio::fs::create_dir_all(root).await?;
        let objects = self.list().await?;
        for object in &objects {
            let Some(relative) = self.relative_path(&object.location) else {
                continue;
            };
            let destination = relative
                .iter()
                .fold(root.to_path_buf(), |path, part| path.join(part));
            if let Some(parent) = destination.parent() {
                tokio::fs::create_dir_all(parent).await?;
            }
            let content = self.store.get(&object.location).await?.bytes().await?;
            tokio::fs::write(destination, content).await?;
        }
        info!(objects = objects.len(), "synchronized sandbox from S3");
        Ok(())
    }

    pub(crate) async fn sync_up(&self, root: &FsPath) -> StorageResult<()> {
        let local = local_files(root)?;
        let mut local_keys = HashSet::with_capacity(local.len());
        for (file, relative) in &local {
            let key = self.object_path(relative)?;
            let content = tokio::fs::read(file).await?;
            self.store.put(&key, content.into()).await?;
            local_keys.insert(key);
        }

        let remote = self.list().await?;
        let mut deleted = 0;
        for object in remote {
            if !local_keys.contains(&object.location) {
                self.store.delete(&object.location).await?;
                deleted += 1;
            }
        }
        info!(objects = local.len(), deleted, "synchronized sandbox to S3");
        Ok(())
    }

    async fn list(&self) -> StorageResult<Vec<ObjectMeta>> {
        Ok(self
            .store
            .list(Some(&self.prefix))
            .try_collect::<Vec<_>>()
            .await?)
    }

    fn relative_path(&self, object: &Path) -> Option<Vec<String>> {
        let parts = object
            .prefix_match(&self.prefix)?
            .map(|part| part.as_ref().to_owned())
            .collect::<Vec<_>>();
        (!parts.is_empty()).then_some(parts)
    }

    fn object_path(&self, relative: &FsPath) -> StorageResult<Path> {
        let relative = relative
            .to_str()
            .ok_or("sandbox file path is not valid UTF-8")?;
        let relative = Path::parse(relative)?;
        let mut result = self.prefix.clone();
        for part in relative.parts() {
            result = result.child(part);
        }
        Ok(result)
    }
}

fn local_files(root: &FsPath) -> StorageResult<Vec<(PathBuf, PathBuf)>> {
    let mut files = Vec::new();
    for entry in WalkDir::new(root).follow_links(false) {
        let entry = entry?;
        if entry.file_type().is_file() {
            files.push((
                entry.path().to_path_buf(),
                entry.path().strip_prefix(root)?.to_path_buf(),
            ));
        }
    }
    Ok(files)
}

#[cfg(test)]
mod tests {
    use super::*;
    use object_store::memory::InMemory;
    use tempfile::TempDir;

    fn syncer() -> S3Sync {
        S3Sync {
            store: Arc::new(InMemory::new()),
            prefix: Path::from("home"),
        }
    }

    #[tokio::test]
    async fn round_trips_and_removes_stale_objects() {
        let sync = syncer();
        let source = TempDir::new().expect("create source");
        tokio::fs::create_dir(source.path().join("nested"))
            .await
            .expect("create directory");
        tokio::fs::write(source.path().join("nested/file.txt"), b"content")
            .await
            .expect("write source");
        sync.store
            .put(&Path::from("home/stale.txt"), b"stale".to_vec().into())
